INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 105, 'uk', 'boundary', '{"key":"105-ice-cream","text":"{{name}} має рівно {{price}} грн. Морозиво коштує {{price}} грн. Монети вкинуто всі, а автомат пише: «Недостатньо коштів».","question":"Що сталося?","options":[{"id":"o1","text":"Морозиво дорожче, ніж написано"},{"id":"o2","text":"Автомат не приймає суму, що дорівнює ціні"},{"id":"o3","text":"Вкинули не ті монети"},{"id":"o4","text":"Автомат зовсім не працює"}]}', '{"type":"single","correct":"o2"}', '{"text":"{{price}} = {{price}} — грошей рівно достатньо. Поломка ховається саме на межі: «більше або дорівнює» плутають із «більше».","hint":"Порівняйте суму й ціну."}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 105 AND payload_json LIKE '%"key":"105-ice-cream"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 105, 'uk', 'boundary', '{"key":"105-tickets","text":"На автоматі квитків написано: «Приймаю купюри від {{lo}} до {{hi}} грн». {{name}} вставляє {{hi}} грн — автомат повертає купюру.","question":"Що сталося?","options":[{"id":"o1","text":"Купюра фальшива"},{"id":"o2","text":"Автомат не приймає найбільшу дозволену купюру"},{"id":"o3","text":"Купюру вставили не тією стороною"},{"id":"o4","text":"Квитки закінчилися"}]}', '{"type":"single","correct":"o2"}', '{"text":"«До {{hi}}» означає й саме {{hi}}. Автомат відкидає крайнє дозволене значення — це поломка на межі.","hint":"Чи входить {{hi}} у «від {{lo}} до {{hi}}»?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 105 AND payload_json LIKE '%"key":"105-tickets"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 105, 'uk', 'boundary', '{"key":"105-parking","text":"Табличка на парковці: «Перші {{minutes}} хв — безкоштовно». Авто стояло рівно {{minutes}} хв, а автомат вимагає оплату.","question":"Що сталося?","options":[{"id":"o1","text":"Годинник автомата спішить"},{"id":"o2","text":"Автомат вважає {{minutes}} хв уже платними"},{"id":"o3","text":"Паркування завжди платне"},{"id":"o4","text":"Авто стояло довше"}]}', '{"type":"single","correct":"o2"}', '{"text":"Рівно {{minutes}} хв — ще безкоштовно. Автомат помиляється саме на межі.","hint":"Чи входить {{minutes}} у «перші {{minutes}} хв»?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 105 AND payload_json LIKE '%"key":"105-parking"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 105, 'uk', 'boundary', '{"key":"105-top-up","text":"Термінал: «Поповнення телефону — від {{lo}} грн». {{name}} поповнює рівно на {{lo}} грн, а термінал пише: «Сума замала».","question":"Що сталося?","options":[{"id":"o1","text":"Треба поповнювати на більше"},{"id":"o2","text":"Термінал не приймає найменшу дозволену суму"},{"id":"o3","text":"Номер телефону неправильний"},{"id":"o4","text":"Термінал вимкнено"}]}', '{"type":"single","correct":"o2"}', '{"text":"«Від {{lo}}» означає й саме {{lo}}. Найменше дозволене значення теж має прийматися.","hint":"Чи входить {{lo}} у «від {{lo}} грн»?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 105 AND payload_json LIKE '%"key":"105-top-up"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 105, 'uk', 'boundary', '{"key":"105-canteen","text":"У шкільній їдальні: «Знижка на замовлення від {{lo}} грн». {{name}} замовляє рівно на {{lo}} грн — знижки немає.","question":"Що сталося?","options":[{"id":"o1","text":"Знижку скасували"},{"id":"o2","text":"Каса не дає знижку на суму, що дорівнює межі"},{"id":"o3","text":"Замовлення замале"},{"id":"o4","text":"Знижка лише для вчителів"}]}', '{"type":"single","correct":"o2"}', '{"text":"Замовлення на {{lo}} грн уже «від {{lo}}». Каса помиляється на межі.","hint":"Порівняйте суму замовлення з межею знижки."}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 105 AND payload_json LIKE '%"key":"105-canteen"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 105, 'uk', 'boundary', '{"key":"105-bike-wash","text":"Мийка роверів: «Колеса до {{size}} дюймів». У ровера колеса рівно {{size}} дюймів, а мийка пише: «Завеликий».","question":"Що сталося?","options":[{"id":"o1","text":"Ровер справді завеликий"},{"id":"o2","text":"Мийка не приймає найбільший дозволений розмір"},{"id":"o3","text":"Колеса брудні"},{"id":"o4","text":"Мийка зламалася повністю"}]}', '{"type":"single","correct":"o2"}', '{"text":"«До {{size}}» включає й {{size}}. Мийка відкидає крайнє дозволене значення.","hint":"Чи входить {{size}} у «до {{size}}»?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 105 AND payload_json LIKE '%"key":"105-bike-wash"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 205, 'uk', 'duplicate', '{"key":"205-parcel","text":"Пані Галина натиснула «Відправити» двічі, бо екран довго думав. У журналі пошти: «№ 4471 — Галина Мельник → Київ, 2 кг, 10:02:15» і «№ 4472 — Галина Мельник → Київ, 2 кг, 10:02:16».","question":"Що тут не так?","options":[{"id":"o1","text":"Одна посилка записана двічі"},{"id":"o2","text":"Посилка заважка"},{"id":"o3","text":"Неправильне місто"},{"id":"o4","text":"Номери йдуть не по порядку"}]}', '{"type":"single","correct":"o1"}', '{"text":"Записи однакові, різниця — одна секунда. Форма мала не приймати друге натискання.","hint":"Порівняйте два записи."}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 205 AND payload_json LIKE '%"key":"205-parcel"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 205, 'uk', 'duplicate', '{"key":"205-chalk","text":"Школа замовила одну коробку крейди, але кнопку «Замовити» натиснули двічі. Прийшло два рахунки по 150 грн з однаковим текстом.","question":"Що тут не так?","options":[{"id":"o1","text":"Крейда подорожчала"},{"id":"o2","text":"Одне замовлення оформлено двічі, і рахунок теж"},{"id":"o3","text":"Школа замовила забагато"},{"id":"o4","text":"Рахунок не дійшов"}]}', '{"type":"single","correct":"o2"}', '{"text":"Одна коробка — один рахунок. Другий однаковий рахунок — це дубль.","hint":"Скільки коробок замовили і скільки рахунків прийшло?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 205 AND payload_json LIKE '%"key":"205-chalk"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 205, 'uk', 'duplicate', '{"key":"205-doctor","text":"Пан Микола записувався до лікаря на 14:00 і двічі торкнувся кнопки. Тепер у розкладі два записи: «Микола Ткач, 14:00» і ще раз «Микола Ткач, 14:00».","question":"Що тут не так?","options":[{"id":"o1","text":"Лікар працює пізно"},{"id":"o2","text":"Той самий запис зʼявився двічі й зайняв чужий час"},{"id":"o3","text":"Неправильне імʼя"},{"id":"o4","text":"Запис не зберігся"}]}', '{"type":"single","correct":"o2"}', '{"text":"Одна людина — один запис. Другий такий самий займає час, який міг би отримати хтось інший.","hint":"Порахуйте записи пана Миколи."}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 205 AND payload_json LIKE '%"key":"205-doctor"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 205, 'uk', 'duplicate', '{"key":"205-transfer","text":"Онук переказав бабусі 200 грн, але сторінка «зависла», і він натиснув ще раз. У виписці два однакові перекази по 200 грн з різницею у дві секунди.","question":"Що тут не так?","options":[{"id":"o1","text":"Бабуся отримала забагато подарунків"},{"id":"o2","text":"Один переказ виконано двічі"},{"id":"o3","text":"Переказ не дійшов"},{"id":"o4","text":"Неправильна сума"}]}', '{"type":"single","correct":"o2"}', '{"text":"Хотіли один переказ, а система провела два однакові. Повторне натискання мало не спрацьовувати.","hint":"Скільки разів хотіли переказати гроші?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 205 AND payload_json LIKE '%"key":"205-transfer"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 205, 'uk', 'duplicate', '{"key":"205-club","text":"Мама записала Дану на гурток малювання. Кнопку натиснула двічі — і в списку гуртка Дана тепер займає два місця з дванадцяти.","question":"Що тут не так?","options":[{"id":"o1","text":"Гурток замалий"},{"id":"o2","text":"Одну дитину записано двічі"},{"id":"o3","text":"Дана не любить малювати"},{"id":"o4","text":"Список зник"}]}', '{"type":"single","correct":"o2"}', '{"text":"Одна дитина — одне місце. Дубль забирає місце в когось іншого.","hint":"Скільки разів у списку імʼя Дани?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 205 AND payload_json LIKE '%"key":"205-club"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 205, 'uk', 'duplicate', '{"key":"205-newspaper","text":"Пан Роман оформив підписку на «Вісті Багвіля» на місяць. Через подвійне натискання щоранку в скриньці дві однакові газети.","question":"Що тут не так?","options":[{"id":"o1","text":"Газета стала товстішою"},{"id":"o2","text":"Підписку оформлено двічі"},{"id":"o3","text":"Листоноша помилився адресою"},{"id":"o4","text":"Газет друкують забагато"}]}', '{"type":"single","correct":"o2"}', '{"text":"Одна підписка — одна газета. Друга однакова газета щоранку — наслідок дубля.","hint":"Скільки підписок хотів пан Роман?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 205 AND payload_json LIKE '%"key":"205-newspaper"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 305, 'uk', 'report', '{"key":"305-shelf","text":"Бібліотекарка Ніна: «За списком на полиці має бути {{n}} книжок, а я рахую {{n1}}».","question":"Як коротко записати поломку для майстра?","options":[{"id":"o1","text":"Очікувано: {{n}} книжок. Фактично: {{n1}}."},{"id":"o2","text":"Очікувано: {{n1}}. Фактично: {{n}}."},{"id":"o3","text":"Книжок забагато"},{"id":"o4","text":"Полиця зламалася"}]}', '{"type":"single","correct":"o1"}', '{"text":"Хороший запис поломки каже, чого чекали і що побачили, без догадок.","hint":"Що мало бути і що є насправді?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 305 AND payload_json LIKE '%"key":"305-shelf"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 305, 'uk', 'report', '{"key":"305-schedule","text":"За розкладом читальна зала відкривається о {{open}}, а електронний замок відчиняє двері о {{late}}.","question":"Як коротко записати поломку для майстра?","options":[{"id":"o1","text":"Очікувано: {{open}}. Фактично: {{late}}."},{"id":"o2","text":"Очікувано: {{late}}. Фактично: {{open}}."},{"id":"o3","text":"Замок поганий"},{"id":"o4","text":"Читачі прийшли зарано"}]}', '{"type":"single","correct":"o1"}', '{"text":"Чекали {{open}}, побачили {{late}}. Це й є короткий звіт (report).","hint":"Що обіцяє розклад і що робить замок?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 305 AND payload_json LIKE '%"key":"305-schedule"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 305, 'uk', 'report', '{"key":"305-queue","text":"У черзі на книжку «{{book}}» читач має місце {{pos}}. Наступного дня сайт бібліотеки показує місце {{pos2}}, хоча книжку ще ніхто не повертав.","question":"Як коротко записати поломку для майстра?","options":[{"id":"o1","text":"Очікувано: місце {{pos}}. Фактично: місце {{pos2}}."},{"id":"o2","text":"Очікувано: місце {{pos2}}. Фактично: місце {{pos}}."},{"id":"o3","text":"Черга задовга"},{"id":"o4","text":"Книжка нецікава"}]}', '{"type":"single","correct":"o1"}', '{"text":"Нічого не змінилося, а номер у черзі став дивним. Записуємо: чекали {{pos}}, побачили {{pos2}}.","hint":"Яке місце мало бути і яке показано?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 305 AND payload_json LIKE '%"key":"305-queue"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 305, 'uk', 'report', '{"key":"305-fine","text":"Правило: штраф {{fine}} грн за кожен день запізнення. Книжку повернули на {{days}} дні пізніше, а каса нарахувала 0 грн.","question":"Як коротко записати поломку для майстра?","options":[{"id":"o1","text":"Очікувано: штраф за {{days}} дні. Фактично: 0 грн."},{"id":"o2","text":"Очікувано: 0 грн. Фактично: штраф."},{"id":"o3","text":"Штрафи — це погано"},{"id":"o4","text":"Каса нова"}]}', '{"type":"single","correct":"o1"}', '{"text":"Чекали штраф за {{days}} дні запізнення, а побачили 0 грн. Звіт без оцінок: лише очікуване й фактичне.","hint":"Скільки мала нарахувати каса?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 305 AND payload_json LIKE '%"key":"305-fine"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 305, 'uk', 'report', '{"key":"305-archive","text":"В архіві має бути не тепліше {{temp}} °C, щоб старі книжки не псувалися. Термометр показує {{temp2}} °C, а кондиціонер не вмикається.","question":"Як коротко записати поломку для майстра?","options":[{"id":"o1","text":"Очікувано: до {{temp}} °C. Фактично: {{temp2}} °C, кондиціонер не вмикається."},{"id":"o2","text":"Очікувано: {{temp2}} °C. Фактично: {{temp}} °C."},{"id":"o3","text":"В архіві спекотно, як улітку"},{"id":"o4","text":"Книжки старі"}]}', '{"type":"single","correct":"o1"}', '{"text":"Хороший звіт містить числа: скільки мало бути і скільки є, і що не спрацювало.","hint":"Яка температура має бути і яка є?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 305 AND payload_json LIKE '%"key":"305-archive"%');
INSERT INTO bv_mission_variants (mission_id, lang, skill, payload_json, answer_json, explain_json, status, created_at) SELECT 305, 'uk', 'report', '{"key":"305-chairs","text":"У читальній залі {{chairs}} стільців. Система бронювання дозволяє записати більше відвідувачів, ніж є стільців.","question":"Як коротко записати поломку для майстра?","options":[{"id":"o1","text":"Очікувано: не більше {{chairs}} броней. Фактично: броней більше, ніж стільців."},{"id":"o2","text":"Очікувано: більше броней. Фактично: {{chairs}}."},{"id":"o3","text":"Стільці незручні"},{"id":"o4","text":"Відвідувачів забагато"}]}', '{"type":"single","correct":"o1"}', '{"text":"Чекали межу {{chairs}}, а система її не тримає. Це й записуємо, без догадок про причину.","hint":"Скільки броней має дозволяти система?"}', 'active', UTC_TIMESTAMP() FROM DUAL WHERE NOT EXISTS (SELECT 1 FROM bv_mission_variants WHERE mission_id = 305 AND payload_json LIKE '%"key":"305-chairs"%');
